    CREATE TABLE "EngineAcknowledgements" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "BusinessUnitId" bigint NOT NULL,
        "CycleKey" character varying(20) NOT NULL,
        "Rung" integer NOT NULL,
        "AcknowledgedByUserId" integer,
        "AcknowledgedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_EngineAcknowledgements" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_EngineAcknowledgements_BusinessUnits_BusinessUnitId" FOREIGN KEY ("BusinessUnitId") REFERENCES "BusinessUnits" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
